"""Every rounding rule of meterbill, in one place."""

from __future__ import annotations

import math
from decimal import Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _parts(value: Decimal) -> tuple:
    sign, digits, exp = value.as_tuple()
    return sign, int("".join(map(str, digits)) or "0"), exp


def _build(sign: int, coef: int, exp: int) -> Decimal:
    return Decimal((sign, tuple(int(c) for c in str(coef)), exp))


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum, with the sign of a zero as decimal addition gives it."""
    sa, ca, ea = _parts(a)
    sb, cb, eb = _parts(b)
    exp = min(ea, eb)
    total = (-ca if sa else ca) * 10 ** (ea - exp) + (-cb if sb else cb) * 10 ** (eb - exp)
    if total == 0:
        return _build(1 if (sa and sb) else 0, 0, exp)
    return _build(1 if total < 0 else 0, abs(total), exp)


def _sub(a: Decimal, b: Decimal) -> Decimal:
    return _add(a, b.copy_negate())


def _sum(values, start: Decimal) -> Decimal:
    total = start
    for v in values:
        total = _add(total, v)
    return total


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")
    sign, coef, exp = _parts(value)
    _, scoef, sexp = _parts(step)
    shift = exp - sexp
    if shift >= 0:
        num, den = coef * 10 ** shift, scoef
    else:
        num, den = coef, scoef * 10 ** -shift
    q, r = divmod(num, den)
    if method == HALF_UP:
        if 2 * r >= den:
            q += 1
    elif method == HALF_EVEN:
        if 2 * r > den or (2 * r == den and q % 2 == 1):
            q += 1
    return _build(sign, q * scoef, sexp)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, cut down to `step`; what the cuts lost against the
    rounded total goes on the last amount that is not zero."""
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = round_amount(_sum(amounts, Decimal("0")), step, HALF_UP)
    zero = _build(0, 0, _parts(step)[2])
    rest = _sub(whole, _sum(parts, zero))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not value.is_finite():
        return format(value, "f")
    return format(round_amount(value, _build(0, 1, -places), method), "f")
